select dr1_0.node_id,dr1_0.account_id,dr1_0.checksum,dr1_0.cluster_id,dr1_0.connector_id,dr1_0.content_type,dr1_0.crawl_id,dr1_0.created_at,dr1_0.datasource_id,dr1_0.delete_source_blobs_on_settle,dr1_0.doc_id,dr1_0.drive_name,dr1_0.etag,dr1_0.filename,dr1_0.graph_address_id,dr1_0.graph_id,dr1_0.last_reprocessed_at,dr1_0.mutation_revision,dr1_0.object_key,dr1_0.part_manifest,dr1_0.pending_purge_id,dr1_0.reprocess_count,dr1_0.row_kind,dr1_0.security,dr1_0.size_bytes,dr1_0.source_blob_delete_reason,dr1_0.status,dr1_0.updated_at,dr1_0.version_id from documents dr1_0 where dr1_0.status=$1 and dr1_0.pending_purge_id is null and not exists(select dpr1_0.purge_id from document_purges dpr1_0 where dpr1_0.node_id=dr1_0.node_id and dpr1_0.status in ($2,$3)) order by dr1_0.created_at,dr1_0.node_id fetch first $4 rows only